// Task-local finite native PCM energy cadence; independent of any chip algorithm.
package main
import("bytes";"crypto/sha256";"encoding/csv";"encoding/json";"flag";"fmt";"math";"os";"sort";"strconv")
type cadence_result struct{State string `json:"state"`;Samples int `json:"samples"`;Minimum float64 `json:"minimum_pcm"`;Maximum float64 `json:"maximum_pcm"`;Peak float64 `json:"peak_absolute_pcm"`;Window int `json:"energy_window_samples"`;Low float64 `json:"power_q10"`;High float64 `json:"power_q99"`;Contrast float64 `json:"power_contrast"`;Threshold float64 `json:"rising_power_midlevel"`;RawCrossings int `json:"raw_rising_crossings"`;Crossings []float64 `json:"clustered_rising_crossings"`;Intervals []float64 `json:"crossing_intervals"`;Period float64 `json:"measured_period_native_samples"`;Bounds []float64 `json:"support_period_bounds_native_samples"`;Spread float64 `json:"interval_max_minus_min_samples"`;Limits []string `json:"limits"`}
func median(v []float64)float64{w:=append([]float64{},v...);sort.Float64s(w);n:=len(w);if n%2!=0{return w[n/2]};return(w[n/2-1]+w[n/2])/2}
func score_energy(v []float64)cadence_result{r:=cadence_result{Samples:len(v),Window:32,Crossings:[]float64{},Intervals:[]float64{},Bounds:[]float64{},Limits:[]string{"Energy cadence only; periodic output is not proof of CSM without independent register/null controls","No expected timer period used in crossing selection or period estimation","32sample rectangular power support,64sample crossing clusters; sub128sample periods unresolved","Period plus/minus64 is finite support screen, not universal statistical accuracy","No exact attackshape, keypulsewidth, eventlatency or physicalIRQ claim"}};if len(v)<1024{r.State="unqualified_short_interval";return r};r.Minimum=v[0];r.Maximum=v[0];for _,x:=range v{if x<r.Minimum{r.Minimum=x};if x>r.Maximum{r.Maximum=x};if math.Abs(x)>r.Peak{r.Peak=math.Abs(x)}};if r.Peak==0{r.State="quiet_exact_zero";return r};if r.Peak<32{r.State="low_level_unresolved";return r};if r.Peak>=32767{r.State="clipped_unqualified";return r};power:=make([]float64,len(v)-31);var sum float64;for i,x:=range v{sum+=x*x;if i>=32{sum-=v[i-32]*v[i-32]};if i>=31{power[i-31]=sum/32}};ordered:=append([]float64{},power...);sort.Float64s(ordered);r.Low=ordered[int(.10*float64(len(ordered)-1))];r.High=ordered[int(.99*float64(len(ordered)-1))];if r.High<=0{r.State="unqualified_sparse_or_missing_energy";return r};r.Contrast=(r.High-r.Low)/r.High;if r.Contrast<.2{r.State="no_resolved_energy_modulation";return r};r.Threshold=(r.Low+r.High)/2;last_raw:=math.Inf(-1);for i:=1;i<len(power);i++{if power[i-1]<r.Threshold&&power[i]>=r.Threshold{x:=float64(i-1)+(r.Threshold-power[i-1])/(power[i]-power[i-1])+15.5;r.RawCrossings++;if x-last_raw>=64{r.Crossings=append(r.Crossings,x)};last_raw=x}};if len(r.Crossings)<5{r.State="unqualified_crossing_coverage";return r};for i:=1;i<len(r.Crossings);i++{r.Intervals=append(r.Intervals,r.Crossings[i]-r.Crossings[i-1])};r.Period=median(r.Intervals);if r.Period<128{r.State="unqualified_fast_energy_cadence";return r};low,high:=r.Intervals[0],r.Intervals[0];for _,x:=range r.Intervals{if x<low{low=x};if x>high{high=x}};r.Spread=high-low;if r.Spread>64{r.State="irregular_or_unresolved_energy";return r};r.Bounds=[]float64{r.Period-64,r.Period+64};r.State="finite_repeated_energy_cadence";return r}
func original_energy_cli_main(){column:=flag.String("column","right","PCM CSV column");first:=flag.Int("start-sample",0,"inclusive interval");end:=flag.Int("end-sample",0,"exclusive interval,0=end");flag.Parse();if e:=run(*column,*first,*end);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func run(column string,first,end int)error{if flag.NArg()!=1{return fmt.Errorf("use [-column NAME] [-start-sample N] [-end-sample N] INPUT.csv")};raw,e:=os.ReadFile(flag.Arg(0));if e!=nil{return e};rows,e:=csv.NewReader(bytes.NewReader(raw)).ReadAll();if e!=nil{return e};if len(rows)<2{return fmt.Errorf("missing CSV rows")};si,vi:=-1,-1;for i,k:=range rows[0]{if k=="sample"{si=i};if k==column{vi=i}};if si<0||vi<0{return fmt.Errorf("missing CSV sample/signal")};v:=make([]float64,len(rows)-1);for i,row:=range rows[1:]{if si>=len(row)||vi>=len(row){return fmt.Errorf("short row")};n,e:=strconv.Atoi(row[si]);if e!=nil||n!=i{return fmt.Errorf("nonconsecutive native samples")};x,e:=strconv.ParseFloat(row[vi],64);if e!=nil||math.IsNaN(x)||math.IsInf(x,0)||x< -32768||x>32767||x!=math.Trunc(x){return fmt.Errorf("invalid integral PCM")};v[i]=x};if end==0{end=len(v)};if first<0||end>len(v)||end<=first{return fmt.Errorf("invalid bounds")};return json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"input":flag.Arg(0),"input_sha256":fmt.Sprintf("%x",sha256.Sum256(raw)),"column":column,"native_stride":1,"first_sample":first,"end_sample_exclusive":end,"result":score_energy(v[first:end])})}
